const WIDTHS = [480, 720, 1024, 1600] as const

type PictureProps = {
  name: string
  alt: string
  sizes: string
  width: number
  height: number
  priority?: boolean
  className?: string
}

/** Responsive AVIF with WebP fallback, generated by scripts/optimise-images.mjs. */
export function Picture({ name, alt, sizes, width, height, priority = false, className = '' }: PictureProps) {
  const srcset = (ext: string) => WIDTHS.map((w) => `/images/${name}-${w}.${ext} ${w}w`).join(', ')
  return (
    <picture>
      <source type="image/avif" srcSet={srcset('avif')} sizes={sizes} />
      <source type="image/webp" srcSet={srcset('webp')} sizes={sizes} />
      <img
        src={`/images/${name}-1024.webp`}
        alt={alt}
        width={width}
        height={height}
        loading={priority ? 'eager' : 'lazy'}
        decoding={priority ? 'sync' : 'async'}
        fetchPriority={priority ? 'high' : 'auto'}
        className={className}
      />
    </picture>
  )
}
